} from 'lucide-react';

function App() {
    const [activeTab, setActiveTab] = useState('home');
    const [isPlaying, setIsPlaying] = useState(false);
    const [isVisible, setIsVisible] = useState(true);
    const [overlayVisible, setOverlayVisible] = useState(true);
    const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
    const [timeLeft, setTimeLeft] = useState({ days: 0, hours: 0, minutes: 0, seconds: 0 });
    const [guestName, setGuestName] = useState('');
    const [rsvpStatus, setRsvpStatus] = useState('');
    const [submitMessage, setSubmitMessage] = useState('');
    const [isSubmitting, setIsSubmitting] = useState(false); // loading state
    const audioRef = useRef(null);

    const weddingDate = "May 21, 2026";
    const weddingTime = "08:00 PM";
    const googleDriveLink = "https://drive.google.com/drive/folders/1-kykFeDTzB3kiq8k840hlp0vAsrGerN2?usp=sharing";
    const googleSheetURL = "https://script.google.com/macros/s/AKfycbzi0aIDzJYKgvSs8u2LXzRxG1XiqyXNV350OZd9sKqO5JowPUHyGqfDFhKltRBjx7z5/exec";

    // Countdown logic
    useEffect(() => {
        const targetDate = new Date("May 21, 2026 20:00:00").getTime();
        const interval = setInterval(() => {
            const now = new Date().getTime();
            const distance = targetDate - now;
            if (distance < 0) {
                clearInterval(interval);
                setTimeLeft({ days: 0, hours: 0, minutes: 0, seconds: 0 });
                return;
            }
            setTimeLeft({
                days: Math.floor(distance / (1000 * 60 * 60 * 24)),
                hours: Math.floor((distance % (1000 * 60 * 60 * 24)) / (1000 * 60 * 60)),
                minutes: Math.floor((distance % (1000 * 60 * 60)) / (1000 * 60)),
                seconds: Math.floor((distance % (1000 * 60)) / 1000),
            });
        }, 1000);
        return () => clearInterval(interval);
    }, []);

    // Fade animation on tab change
    useEffect(() => {
        setIsVisible(false);
        const timer = setTimeout(() => setIsVisible(true), 100);
        return () => clearTimeout(timer);
    }, [activeTab]);

    // Play/pause audio
    useEffect(() => {
        if (audioRef.current) {
            if (isPlaying) audioRef.current.play();
            else audioRef.current.pause();
        }
    }, [isPlaying]);

    // Handle RSVP submission
    const handleRSVP = async (status) => {
        if (!guestName.trim()) {
            setSubmitMessage("Please enter your name");
            return;
        }

        setRsvpStatus(status);
        setIsSubmitting(true);
        setSubmitMessage("Submitting...");

        try {
            const res = await fetch(googleSheetURL, {
                method: "POST",
                headers: {
                    "Content-Type": "application/json"
                },
                body: JSON.stringify({ name: guestName, rsvp: status })
            });

            const data = await res.json();

            if (data.result === "success") {
                setSubmitMessage("RSVP submitted successfully!");
                setGuestName(""); // Clear input
            } else {
                setSubmitMessage("Failed to submit. Please try again.");
            }
        } catch (err) {
            console.error("RSVP error:", err);
            setSubmitMessage("Failed to submit. Please try again.");
        } finally {
            setIsSubmitting(false);
        }
    };

    const TabButton = ({ id, label, icon: Icon }) => (
        <button
            onClick={() => { setActiveTab(id); setMobileMenuOpen(false); }}
            className={`flex items-center space-x-2 px-3 py-2 rounded-full transition-all duration-300 text-sm md:text-xs ${
                activeTab === id
                    ? 'bg-[#D4AF37] text-white'
                    : 'text-[#4A4238] hover:bg-[#D4AF37]/20'
            }`}
        >
            <Icon size={16} />
            <span className="uppercase tracking-widest font-bold">{label}</span>
        </button>
    );

    const handleOverlayClick = () => {
        if (audioRef.current) { audioRef.current.play(); setIsPlaying(true); }
        setOverlayVisible(false);
    };

    return (
        <div className="min-h-screen bg-[#FFFBF5] text-[#4A4238] font-serif relative">
            <audio ref={audioRef} src="/audio/fathiha.mp3" loop />
            {overlayVisible && (
                <div onClick={handleOverlayClick} className="fixed inset-0 bg-black/80 z-50 flex items-center justify-center text-white text-center px-4 cursor-pointer">
                    <div>
                        <p className="text-2xl md:text-4xl font-semibold">Tap anywhere to start audio</p>
                        <p className="text-sm mt-2 opacity-70">Please allow audio to enjoy the experience</p>
                    </div>
                </div>
            )}

            {/* Navbar */}
            <nav className="fixed top-0 w-full z-40 bg-white/70 backdrop-blur border-b border-[#D4AF37]/20 px-4 md:px-6 py-4">
                <div className="max-w-6xl mx-auto flex justify-between items-center">
                    <h2 className="text-xl italic">Shazeen <span className="text-[#D4AF37]">&</span> Shimra</h2>
                    <div className="hidden md:flex space-x-2">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                    <div className="md:hidden">
                        <button onClick={() => setMobileMenuOpen(!mobileMenuOpen)}>
                            {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
                        </button>
                    </div>
                </div>
                {mobileMenuOpen && (
                    <div className="flex flex-col items-center space-y-2 mt-2 md:hidden">
                        <TabButton id="home" label="Home" icon={Home} />
                        <TabButton id="invitation" label="Invitation" icon={MailOpen} />
                        <TabButton id="location" label="Location" icon={MapPin} />
                    </div>
                )}
            </nav>

            <main className={`pt-28 px-4 md:px-6 lg:px-12 transition-all duration-700 ${isVisible ? 'opacity-100' : 'opacity-0'}`}>
                {/* HOME */}
                {activeTab === 'home' && (
                    <section className="min-h-[80vh] flex flex-col items-center justify-center text-center space-y-6 md:space-y-8 px-2 md:px-0">
                        <span className="border-y border-[#D4AF37] px-4 py-1 text-[#D4AF37] text-xs tracking-[0.3em] uppercase">Together with their families</span>
                        <h1 className="text-4xl sm:text-5xl md:text-6xl lg:text-9xl font-light italic text-center leading-tight">Shazeen<span className="text-[#D4AF37] mx-2 md:mx-4">&</span>Shimra</h1>
                        <p className="italic opacity-70 text-lg md:text-xl">
                            Cordially invite you to celebrate their
                            <span className="block text-2xl md:text-3xl mt-2 not-italic">Wedding Function</span>
                        </p>

                        <div className="mt-8 md:mt-12">
                            <p className="text-4xl md:text-5xl text-[#D4AF37]">{weddingDate}</p>
                            <p className="uppercase text-xs md:text-sm tracking-widest mt-2">Pearl Grand Banquet Hall</p>
                        </div>

                        {/* Countdown */}
                        <div className="mt-8 md:mt-12 flex flex-wrap justify-center gap-4 md:gap-6 text-[#4A4238]">
                            {['Days', 'Hours', 'Minutes', 'Seconds'].map((label, index) => {
                                const value = timeLeft[label.toLowerCase()];
                                return (
                                    <div key={index} className="flex flex-col items-center bg-[#D4AF37]/10 px-4 py-3 rounded-2xl w-[60px] sm:w-[70px] md:w-[90px]">
                                        <span className="text-xl sm:text-2xl md:text-3xl font-bold">{value}</span>
                                        <span className="text-[10px] sm:text-xs md:text-sm uppercase tracking-widest text-center">{label}</span>
                                    </div>
                                );
                            })}
                        </div>

                        <button onClick={() => setActiveTab('invitation')} className="flex flex-col items-center text-[#D4AF37] mt-6 md:mt-8">
                            <span className="text-xs uppercase tracking-widest font-bold">More Details</span>
                            <ChevronDown className="animate-bounce mt-1 md:mt-2" />
                        </button>
                    </section>
                )}

                {/* INVITATION with RSVP */}
                {activeTab === 'invitation' && (
                    <section className="max-w-4xl mx-auto bg-white/50 rounded-3xl p-6 md:p-10 shadow-xl space-y-6 md:space-y-10 text-center">
                        <Heart className="mx-auto text-[#D4AF37]" size={40} md={48} />
                        <h2 className="text-3xl md:text-5xl italic font-light">The Invitation</h2>
                        <p className="text-sm md:text-lg opacity-80">
                            We warmly invite you to join us as we begin our journey together.
                            Your presence, prayers, and blessings mean everything to us.
                        </p>

                        <div className="grid gap-4 md:gap-8 md:grid-cols-3 border-y py-6 md:py-8">
                            <div>
                                <MapPin className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-1 md:mt-2 tracking-widest">Location</p>
                                <p className="text-sm md:text-base">Pearl Grand Banquet Hall</p>
                            </div>
                            <div>
                                <Calendar className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-1 md:mt-2 tracking-widest">Date</p>
                                <p className="text-sm md:text-base">21st May 2026</p>
                            </div>
                            <div>
                                <Clock className="mx-auto text-[#D4AF37]" />
                                <p className="uppercase text-xs mt-1 md:mt-2 tracking-widest">Time</p>
                                <p className="text-sm md:text-base">{weddingTime}</p>
                            </div>
                        </div>

                        {/* RSVP Form */}
                        <div className="mt-6 flex flex-col items-center space-y-4">
                            <input
                                type="text"
                                placeholder="Enter your name"
                                value={guestName}
                                onChange={(e) => setGuestName(e.target.value)}
                                className="px-4 py-2 border border-[#D4AF37] rounded-full w-72 text-center focus:outline-none"
                                disabled={isSubmitting}
                            />
                            <div className="flex gap-4">
                                <button
                                    onClick={() => handleRSVP("Yes")}
                                    className="px-6 py-2 bg-[#D4AF37] text-white rounded-full font-bold hover:bg-[#b78e29]"
                                    disabled={isSubmitting}
                                >
                                    {isSubmitting && rsvpStatus === "Yes" ? "Submitting..." : "Yes"}
                                </button>
                                <button
                                    onClick={() => handleRSVP("No")}
                                    className="px-6 py-2 bg-[#D4AF37]/20 text-[#4A4238] rounded-full font-bold hover:bg-[#D4AF37]/30"
                                    disabled={isSubmitting}
                                >
                                    {isSubmitting && rsvpStatus === "No" ? "Submitting..." : "No"}
                                </button>
                            </div>
                            {submitMessage && (
                                <p className={`mt-2 font-semibold ${submitMessage.includes("success") ? "text-green-600" : "text-red-600"}`}>
                                    {submitMessage}
                                </p>
                            )}
                        </div>

                        <a
                            href={googleDriveLink}
                            target="_blank"
                            rel="noreferrer"
                            className="inline-flex items-center w-full md:w-auto justify-center px-6 py-3 md:px-8 md:py-4 bg-[#D4AF37] text-white rounded-full uppercase tracking-widest text-xs md:text-sm font-bold mt-6"
                        >
                            <Upload className="mr-2" />
                            Upload Memories
                        </a>
                    </section>
                )}
            </main>

            {/* MUSIC BUTTON */}
            <button
                onClick={() => setIsPlaying(!isPlaying)}
                className="fixed bottom-4 md:bottom-6 right-4 md:right-6 w-14 h-14 md:w-16 md:h-16 bg-white/90 rounded-full shadow-2xl flex items-center justify-center text-[#D4AF37] z-40"
            >
                {isPlaying ? <Music2 className="animate-pulse" /> : <Music />}
                <div className="absolute -top-1 -right-1 w-5 h-5 bg-[#D4AF37] rounded-full flex items-center justify-center text-[8px] text-white font-bold">
                    {isPlaying ? 'ON' : 'OFF'}
                </div>
            </button>

            <footer className="py-4 md:py-6 text-center text-xs tracking-widest opacity-40">
                &copy; 2026 Mohamed Shazeen. All Rights Reserved.
            </footer>
        </div>
    );
}

export default App;
